mapper.select:
SELECT gc.cooperation_id, gc.merchant_id, me.merchant_name, gc.guide_id, ge.real_name as guide_name, su.avatar as guide_avatar, gc.cooperation_type, CASE gc.cooperation_type WHEN 1 THEN '独家合作' WHEN 2 THEN '合作伙伴' WHEN 3 THEN '项目合作' ELSE '未知' END as cooperation_type_name, gc.start_date, gc.end_date, gc.conditions, gc.notes, gc.status, CASE gc.status WHEN 0 THEN '待确认' WHEN 1 THEN '已接受' WHEN 2 THEN '已拒绝' WHEN 3 THEN '已结束' ELSE '未知' END as status_name, gc.reject_reason, gc.create_time, gc.update_time, gc.response_time FROM guide_cooperation gc LEFT JOIN merchant_extend me ON gc.merchant_id = me.merchant_id LEFT JOIN guide_extend ge ON gc.guide_id = ge.guide_id LEFT JOIN sys_user su ON ge.user_id = su.user_id
AND gc.merchant_id = #{merchantId}
AND gc.status = #{status}
ORDER BY gc.create_time DESC

SELECT COUNT(*)
FROM guide_cooperation
WHERE merchant_id = #{merchantId}

    AND status = #{status}
